    "correctAnswer": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT & PRINCIPLE:\nMolecular mechanism of protein denaturation.\n\n2. GIVEN INFORMATION / DATA:\nNative protein subjected to physical changes (temperature) or chemical changes (pH).\n\n3. FORMULA / EQUATION:\nDenaturation disrupts weak non-covalent interactions (H-bonds, ionic, hydrophobic), leaving covalent peptide bonds intact.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Denaturation of a protein occurs when heat, extremes of pH, or chemical denaturants disrupt the delicate non-covalent bonds (hydrogen bonds, ionic bridges, van der Waals, and hydrophobic interactions) maintaining its native three-dimensional conformation.\n2. Globules unfold and helices get uncoiled, destroying the secondary, tertiary, and quaternary structures and causing total loss of biological enzymatic activity.\n3. However, strong covalent peptide bonds ($-\\text{CONH}-$) linking adjacent amino acids are not cleaved under mild denaturation conditions.\n4. Therefore, the primary structure (the exact covalent sequence of amino acids) remains completely intact and unaffected.\n\n5. FINAL CONCLUSION:\nPrimary structure (linear sequence of amino acids linked by peptide bonds)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nSecondary, tertiary, and quaternary structures are completely destroyed during denaturation.",
