    "correctIndex": 3,
    "explanation": "1. CONCEPT & PRINCIPLE:\nChirality of natural $\\alpha$-amino acids.\n\n2. GIVEN INFORMATION / DATA:\n20 standard proteinogenic $\\alpha$-amino acids.\n\n3. FORMULA / EQUATION:\nGeneral formula: $R-CH(NH_2)-COOH$. Chiral center exists when $R \\ne H, NH_2, COOH$.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. In all standard $\\alpha$-amino acids except glycine, the central $\\alpha$-carbon is bonded to four distinct chemical groups: a carboxyl group ($-COOH$), an amino group ($-NH_2$), a hydrogen atom ($-H$), and a side chain ($-R$).\n2. In glycine, the side chain is simply a hydrogen atom ($R = -H$).\n3. Consequently, the $\\alpha$-carbon of glycine is bonded to two identical hydrogen atoms ($H_2N-CH_2-COOH$), making it superimposable on its mirror image (achiral).\n4. Therefore, glycine does not possess an asymmetric carbon and is the only optically inactive natural amino acid.\n\n5. FINAL CONCLUSION:\nGlycine ($\\text{H}_2\\text{N}-\\text{CH}_2-\\text{COOH}$)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nAlanine ($R=-CH_3$), Valine ($R=-CH(CH_3)_2$), and Leucine ($R=-CH_2CH(CH_3)_2$) all have asymmetric chiral $\\alpha$-carbons and are optically active.",
