    "explanation": "1. CONCEPT & PRINCIPLE:\nWatson-Crick base pairing and Chargaff's equivalence rules in double-stranded DNA.\n\n2. GIVEN INFORMATION / DATA:\nDouble-stranded DNA with complementary base pairing.\n\n3. FORMULA / EQUATION:\nPurines: Adenine ($A$), Guanine ($G$); Pyrimidines: Thymine ($T$), Cytosine ($C$). Complementarity: $A=T$ (2 H-bonds) and $G\\equiv C$ (3 H-bonds).\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Erwin Chargaff established that in native double-helical DNA, adenine always pairs specifically with thymine via two hydrogen bonds ($A = T$), so the molar amount of adenine equals thymine ($[A] = [T]$).\n2. Similarly, guanine pairs specifically with cytosine via three hydrogen bonds ($G \\equiv C$), so $[G] = [C]$.\n3. Summing purines and pyrimidines: $[A] + [G] = [T] + [C]$.\n4. Thus, the total ratio of purines to pyrimidines is strictly $1.0$ (i.e., $\\frac{A+G}{T+C} = 1$).\n5. (Note: The ratio $\\frac{A+T}{G+C}$ varies widely across different biological species).\n\n5. FINAL CONCLUSION:\n$A + G = T + C$ (and $A = T, G = C$)\n\n6. OPTION ANALYSIS & COMMON TRAPS:\n$A+T$ is rarely equal to $G+C$; $A=C$ is completely false because $A$ pairs with $T$.",
    "solutionStructured": {
      "concept": "Watson-Crick base pairing and Chargaff's equivalence rules in double-stranded DNA.",
      "given": "Double-stranded DNA with complementary base pairing.",
      "formula": "Purines: Adenine ($A$), Guanine ($G$); Pyrimidines: Thymine ($T$), Cytosine ($C$). Complementarity: $A=T$ (2 H-bonds) and $G\\equiv C$ (3 H-bonds).",
      "stepByStep": "1. Erwin Chargaff established that in native double-helical DNA, adenine always pairs specifically with thymine via two hydrogen bonds ($A = T$), so the molar amount of adenine equals thymine ($[A] = [T]$).\n2. Similarly, guanine pairs specifically with cytosine via three hydrogen bonds ($G \\equiv C$), so $[G] = [C]$.\n3. Summing purines and pyrimidines: $[A] + [G] = [T] + [C]$.\n4. Thus, the total ratio of purines to pyrimidines is strictly $1.0$ (i.e., $\\frac{A+G}{T+C} = 1$).\n5. (Note: The ratio $\\frac{A+T}{G+C}$ varies widely across different biological species).",
      "finalAnswer": "$A + G = T + C$ (and $A = T, G = C$)",
      "whyOtherOptionsWrong": "$A+T$ is rarely equal to $G+C$; $A=C$ is completely false because $A$ pairs with $T$."
    },
