    "question": "Q69. In a double-stranded DNA molecule, Chargaff's rules state that the molar ratio of purine bases to pyrimidine bases is always equal to 1, meaning:",
    "options": {
      "A": "$A + G = T + C$ (and $A = T, G = C$)",
      "B": "$A + T = G + C$",
      "C": "$A = C$ and $G = T$",
      "D": "$A + C = G + T$ only in single-stranded RNA"
    },
