    "correctIndex": 3,
    "explanation": "1. CONCEPT & PRINCIPLE:\nVitamins, biological roles, and deficiency disorders.\n\n2. GIVEN INFORMATION / DATA:\nVitamin C (L-ascorbic acid, water-soluble vitamin).\n\n3. FORMULA / EQUATION:\nVitamin C is essential for proline and lysine hydroxylation during collagen biosynthesis.\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Vitamin C (ascorbic acid) is a vital water-soluble antioxidant required as a cofactor for prolyl hydroxylase in collagen synthesis.\n2. In deficiency of Vitamin C, defective collagen synthesis leads to fragility of capillary blood vessels, bleeding gums, tooth loosening, petechiae, and delayed wound healing.\n3. This clinical condition is scurvy.\n4. Rickets is caused by Vitamin D deficiency; Beriberi is caused by Vitamin $B_1$ (thiamine) deficiency; Pernicious anemia is caused by Vitamin $B_{12}$ (cobalamin) deficiency.\n\n5. FINAL CONCLUSION:\nScurvy\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nRickets is due to Vitamin D deficiency; Beriberi is due to Vitamin $B_1$; Pernicious anemia is due to Vitamin $B_{12}$.",
