    "id": "bioch-mcq-121",
    "questionNumber": 121,
    "question": "Q121. Sucrose is dextrorotatory ($+66.5^\\circ$), but on hydrolysis with dilute acid it gives a mixture that is laevorotatory ($-39.9^\\circ$). This hydrolytic mixture is called:",
    "options": {
      "A": "Invert sugar",
      "B": "Malt sugar",
      "C": "Cane sugar",
      "D": "Fruit sugar"
    },
    "optionsList": [
      "Invert sugar",
      "Malt sugar",
      "Cane sugar",
      "Fruit sugar"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT & PRINCIPLE:\nInversion of cane sugar (sucrose) upon hydrolysis.\n\n2. GIVEN INFORMATION / DATA:\nSucrose: $[\u0007lpha]_D = +66.5^\\circ$; Hydrolysis produces equimolar D-(+)-glucose ($+52.5^\\circ$) and D-(-)-fructose ($-92.4^\\circ$).\n\n3. FORMULA / EQUATION:\n$C_{12}H_{22}O_{11} + H_2O \\xrightarrow{H^+} C_6H_{12}O_6 \\text{ (glucose)} + C_6H_{12}O_6 \\text{ (fructose)}$\n\n4. STEP-BY-STEP REASONING & CALCULATION:\n1. Sucrose is a non-reducing disaccharide with an initial specific dextrorotation of $+66.5^\\circ$.\n2. Hydrolysis cleaves the $\\alpha-1,\\beta-2$ glycosidic linkage, releasing an equimolar mixture of D-(+)-glucose and D-(-)-fructose.\n3. The specific optical rotation of D-(+)-glucose is $+52.5^\\circ$, whereas that of D-(-)-fructose is $-92.4^\\circ$.\n4. Because the laevorotation of fructose exceeds the dextrorotation of glucose, the net specific rotation of the resulting equimolar mixture is negative (approximately $-39.9^\\circ / 2 = -19.95^\\circ$, laevorotatory).\n5. Since the direction of optical rotation changes from dextro (+) to laevo (-), the process is called inversion of sugar, and the resulting mixture is termed invert sugar.\n\n5. FINAL CONCLUSION:\nInvert sugar\n\n6. OPTION ANALYSIS & COMMON TRAPS:\nMalt sugar is maltose; cane sugar is unhydrolyzed sucrose; fruit sugar is pure fructose.",
    "solutionStructured": {
      "concept": "Inversion of cane sugar (sucrose) upon hydrolysis.",
      "given": "Sucrose: $[\u0007lpha]_D = +66.5^\\circ$; Hydrolysis produces equimolar D-(+)-glucose ($+52.5^\\circ$) and D-(-)-fructose ($-92.4^\\circ$).",
      "formula": "$C_{12}H_{22}O_{11} + H_2O \\xrightarrow{H^+} C_6H_{12}O_6 \\text{ (glucose)} + C_6H_{12}O_6 \\text{ (fructose)}$",
      "stepByStep": "1. Sucrose is a non-reducing disaccharide with an initial specific dextrorotation of $+66.5^\\circ$.\n2. Hydrolysis cleaves the $\\alpha-1,\\beta-2$ glycosidic linkage, releasing an equimolar mixture of D-(+)-glucose and D-(-)-fructose.\n3. The specific optical rotation of D-(+)-glucose is $+52.5^\\circ$, whereas that of D-(-)-fructose is $-92.4^\\circ$.\n4. Because the laevorotation of fructose exceeds the dextrorotation of glucose, the net specific rotation of the resulting equimolar mixture is negative (approximately $-39.9^\\circ / 2 = -19.95^\\circ$, laevorotatory).\n5. Since the direction of optical rotation changes from dextro (+) to laevo (-), the process is called inversion of sugar, and the resulting mixture is termed invert sugar.",
      "finalAnswer": "Invert sugar",
      "whyOtherOptionsWrong": "Malt sugar is maltose; cane sugar is unhydrolyzed sucrose; fruit sugar is pure fructose."
    },
